    /// Base directory for schema files
    schema_dir: PathBuf,
    /// In-memory cache of loaded schemas
    cache: tokio::sync::RwLock<HashMap<String, PluginSchema>>,
    /// Whether to enforce strict validation
    strict: bool,
}

