/// Monitor a database for changes via periodic polling.
///
/// The daemon's D-Bus notification methods (`pop_notification`,
/// `drain_notifications`, `new_stream`) are stubs, so we poll `dump_db`
/// at a fixed interval and deliver full snapshots through the channel.
/// Each snapshot has the shape `{ "TableName": [ row, … ], … }`.
pub async fn monitor_db(&self, db: &str) -> Result<tokio::sync::mpsc::Receiver<Value>> {
    // Validate the database name early so callers get an immediate error
    // if the daemon is unreachable.
    let _ = self.get_schema(db).await?;

    let (tx, rx) = tokio::sync::mpsc::channel(100);
    let self_timeout = self.timeout;
    let db_owned = db.to_string();

    tokio::spawn(async move {
        let client = Self::new().with_timeout(self_timeout);
        let mut interval = tokio::time::interval(Duration::from_secs(5));
        // First tick fires immediately → delivers the initial snapshot.
        interval.tick().await;

        loop {
            match client.dump_db(&db_owned).await {
                Ok(snapshot) => {
                    if tx.send(snapshot).await.is_err() {
                        info!("monitor_db: receiver dropped, stopping poll loop");
                        break;
                    }
                }
                Err(e) => {
                    warn!("monitor_db: dump_db failed: {}, will retry", e);
                }
            }
            interval.tick().await;
        }
    });

    Ok(rx)
}

/// Expose the underlying D-Bus connection so callers can register
/// additional interfaces on the same bus name.
pub fn connection(&self) -> &Connection {
    &self.connection
}

/// Get or create a MirrorSession for a peer.
///
/// Per Property 1: if no session exists for the given peer name,
/// create one with an empty subscribed-paths set and zero sequence
/// numbers.
pub fn get_or_create_session(&self, peer_name: &str) {
    self.sessions
        .entry(peer_name.to_string())
        .or_insert_with(|| session::MirrorSession::new(peer_name.to_string()));
}

/// Destroy a MirrorSession for a peer.
///
/// Per Property 4: when NameOwnerChanged indicates the peer is gone,
/// the session is removed and InterfacesRemoved is emitted for all
/// subscribed paths.
pub async fn destroy_session(&self, peer_name: &str) {
    if let Some((_, session)) = self.sessions.remove(peer_name) {
        for path in &session.subscribed_paths {
            self.emit_interfaces_removed(path).await;
        }
        tracing::info!("Destroyed session for peer {}", peer_name);
    }
}

